269	    /**
270	     * Save an owner, enforcing the create-time business rules.
271	     *
272	     * <p>Because the household is keyed on {@code (lastName, postcode)} (see
273	     * {@link Owner#householdId(String, String)}), owners sharing a last name and postcode are the
274	     * same household. On create, a second owner in an existing household is rejected as a household
275	     * duplicate (see {@link #assertHouseholdIsUnique(Owner)}) <em>unless</em> {@code sharesHousehold}
276	     * is set, in which case it is accepted as a declared household member. The {@code sharesHousehold}
277	     * flag therefore only bypasses that duplicate block; a declared member is also not flagged as a
278	     * possible (suspected) duplicate.
279	     */
280	    @Override
281	    @Transactional
282	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
283	        boolean isCreate = owner.isNew();
284	        assertIdentityIsUnique(owner);
285	        if (owner.isNew()) {
286	            assertCityHasCapacity(owner);
287	            if (!sharesHousehold) {
288	                assertHouseholdIsUnique(owner);
289	            }
290	        }
291	        if (owner.getRegistrationDate() == null) {
292	            owner.setRegistrationDate(LocalDate.now());
293	        }
294	        assertRegistrationDateNotInFuture(owner);
295	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
296	        if (owner.isNew()) {
297	            assertDailyRegistrationLimit(owner);
298	            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
299	        }
300	        if (owner.isNew() && owner.getCustomerCode() == null) {
301	            owner.setCustomerCode(generateCustomerCode(owner));
302	        }
303	        if (owner.isNew() && owner.getNamesakeCount() == null) {
304	            owner.setNamesakeCount(countNamesakes(owner));
305	        }
306	        if (owner.isNew()) {
307	            assignPossibleDuplicate(owner, sharesHousehold);
308	        }
309	        ownerRepository.save(owner);
310	        if (isCreate) {
311	            AUDIT.info("owner created id={} customerCode={} registrationDate={}",
312	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
313	        }
314	    }
315	
316	    /**
317	     * Count the existing owners that, at the moment this owner is created, share its first name
318	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
319	     * it never counts itself. This value is deterministic given the current data, so it is computed
320	     * once at creation time and stored.
321	     */
322	    private Integer countNamesakes(Owner owner) {
323	        String firstName = owner.getFirstName();
324	        String lastName = owner.getLastName();
325	        if (firstName == null || lastName == null) {
326	            return 0;
327	        }
328	        return (int) ownerRepository.findAll().stream()
329	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
330	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
331	                && lastName.equalsIgnoreCase(existing.getLastName()))
332	            .count();
333	    }
334	
335	    /**
336	     * Build an owner's {@code customerCode} formatted {@code '<REGION>-<HASH8>'}, where {@code REGION}
337	     * is the region code derived from the owner's postcode (or {@code 'UNKNOWN'} when no region can be
338	     * derived) and {@code HASH8} is the first eight upper-cased hex characters of SHA-256 over the
339	     * owner's normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The
340	     * value is deterministic in those fields and carries no sequence number (see
341	     * {@link Owner#customerCode(String, String, String)}).
342	     */
343	    private String generateCustomerCode(Owner owner) {
344	        return Owner.customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName());
345	    }
346	
347	    /**
348	     * Flag a newly created owner as a possible (soft) duplicate of an existing owner. A hard
349	     * duplicate (an owner reusing an existing normalized telephone) has already been rejected by
350	     * {@link #assertIdentityIsUnique(Owner)}, and an undeclared household duplicate by
351	     * {@link #assertHouseholdIsUnique(Owner)}, before this runs. This detects the weaker overlap: an
352	     * existing owner that shares this owner's household id (same last name and postcode, see
353	     * {@link Owner#householdId(String, String)}) but has a <em>different</em> normalized telephone.
354	     * When such an owner exists, {@code possibleDuplicate} is set {@code true} and
355	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match);
356	     * otherwise {@code possibleDuplicate} is set {@code false} and {@code possibleDuplicateOf} left unset.
357	     *
358	     * <p>A declared household member ({@code sharesHousehold} set) is never a suspected duplicate: it
359	     * deliberately joins an existing household, so it is left unflagged.
360	     */
361	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
362	        if (sharesHousehold) {
363	            owner.setPossibleDuplicate(false);
364	            owner.setPossibleDuplicateOf(null);
365	            return;
366	        }
367	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
368	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
369	        Integer match = null;
370	        if (householdId != null) {
371	            match = ownerRepository.findAll().stream()
372	                .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
373	                .filter(existing -> householdId.equals(
374	                    Owner.householdId(existing.getLastName(), existing.getPostcode())))
375	                .filter(existing -> !Objects.equals(normalizedTelephone,
376	                    Owner.normalizeTelephone(existing.getTelephone())))
377	                .map(Owner::getId)
378	                .filter(Objects::nonNull)
379	                .min(Integer::compareTo)
380	                .orElse(null);
381	        }
382	        owner.setPossibleDuplicate(match != null);
383	        owner.setPossibleDuplicateOf(match);
384	    }
385	
386	    /**
387	     * Enforce that no <em>other</em> owner already shares this owner's derived identity, throwing
388	     * {@link DuplicateIdentityException} if one does. This single check consolidates the former
389	     * separate telephone, email and household duplicate checks into the one {@code identityKey}
390	     * (normalized telephone, normalized email (or empty) and household id, see
391	     * {@link Owner#identityKey(String, String, String, String)}).
392	     *
393	     * <p>Because the telephone is part of the key, two owners can only ever collide on the whole
394	     * key when their normalized telephones already match; the normalized telephone is therefore the
395	     * decisive component and is what this check compares. Consequently two members of the same
396	     * household with different telephones have different identity keys and are both allowed, while
397	     * an owner reusing an existing normalized telephone is rejected. The owner being saved is
398	     * excluded by id so updating an owner in place never conflicts with itself.
399	     */
400	    private void assertIdentityIsUnique(Owner owner) {
401	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
402	        if (normalizedTelephone == null) {
403	            return;
404	        }
405	        boolean duplicate = ownerRepository.findAll().stream()
406	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
407	            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
408	            .anyMatch(normalizedTelephone::equals);
409	        if (duplicate) {
410	            throw new DuplicateIdentityException(Owner.identityKey(
411	                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()));
412	        }
413	    }
414	
415	    /**
416	     * Enforce that no <em>other</em> owner already belongs to this owner's household, throwing
417	     * {@link DuplicateIdentityException} if one does. The household is keyed on {@code (lastName,
418	     * postcode)} (see {@link Owner#householdId(String, String)}), so owners sharing a last name and
419	     * postcode are the same household and a second such owner is a household duplicate. The owner
420	     * being saved is excluded by id, and an owner with no derivable household id (missing last name
421	     * or postcode) places no constraint. Callers bypass this check for a declared household member
422	     * ({@code sharesHousehold} set).
423	     */
424	    private void assertHouseholdIsUnique(Owner owner) {
425	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
426	        if (householdId == null) {
427	            return;
428	        }
429	        boolean duplicate = ownerRepository.findAll().stream()
430	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
431	            .map(existing -> Owner.householdId(existing.getLastName(), existing.getPostcode()))
432	            .anyMatch(householdId::equals);
433	        if (duplicate) {
434	            throw new DuplicateIdentityException(Owner.identityKey(
435	                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()));
436	        }
437	    }
438	
439	    /**
440	     * Enforce that the owner's city has not yet reached its capacity, throwing
441	     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
442	     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
443	     */
444	    private void assertCityHasCapacity(Owner owner) {
445	        String city = owner.getCity();
446	        if (city == null) {
447	            return;
448	        }
449	        long count = ownerRepository.findAll().stream()
450	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
451	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
452	            .count();
453	        if (count >= MAX_OWNERS_PER_CITY) {
454	            throw new CityAtCapacityException(city);
455	        }
456	    }
457	
458	    /**
459	     * Enforce that the owner's registration date is not later than the current server date, throwing
460	     * {@link FutureRegistrationDateException} when it is. A registration date may not be in the
461	     * future; a date defaulted to {@link LocalDate#now()} is never in the future, so this check is a
462	     * harmless no-op for that case.
463	     */
464	    private void assertRegistrationDateNotInFuture(Owner owner) {
465	        LocalDate registrationDate = owner.getRegistrationDate();
466	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
467	            throw new FutureRegistrationDateException(registrationDate);
468	        }
469	    }
470	
471	    /**
472	     * Roll a registration date forward to the next business day. A date that falls on a Saturday or
473	     * Sunday is advanced to the following Monday; a weekday is returned unchanged. This is applied to
474	     * the effective registration date (whether supplied in the request or defaulted to the server
475	     * date) so that every value derived from it&mdash;such as the membership number's year segment
476	     * and the daily create-limit counting&mdash;uses the adjusted business day.
477	     */
478	    private static LocalDate rollToBusinessDay(LocalDate date) {
479	        if (date == null) {
480	            return null;
481	        }
482	        DayOfWeek dayOfWeek = date.getDayOfWeek();
483	        if (dayOfWeek == DayOfWeek.SATURDAY) {
484	            return date.plusDays(2);
485	        }
486	        if (dayOfWeek == DayOfWeek.SUNDAY) {
487	            return date.plusDays(1);
488	        }
489	        return date;
490	    }
491	
492	    /**
493	     * Enforce that the owner's registration day has not yet reached its capacity, throwing
494	     * {@link DailyRegistrationLimitException} when {@link #MAX_OWNERS_PER_DAY} or more owners are
495	     * already registered on that day (counted by {@code registrationDate}). The owner being saved
496	     * is excluded by id.
497	     */
498	    private void assertDailyRegistrationLimit(Owner owner) {
499	        LocalDate registrationDate = owner.getRegistrationDate();
500	        if (registrationDate == null) {
501	            return;
502	        }
503	        long count = ownerRepository.findAll().stream()
504	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
505	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
506	            .count();
507	        if (count >= MAX_OWNERS_PER_DAY) {
508	            throw new DailyRegistrationLimitException(registrationDate);
509	        }
510	    }
511	
512	    /**
513	     * Compute whether a newly created owner should carry a bulk-signup warning, i.e. whether more
514	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created on this owner's
515	     * registration day (counted by {@code registrationDate}, excluding the owner being saved). Like
516	     * the daily-limit rule this reflects the state at creation time, so it is computed once and
517	     * stored on the owner.
518	     */
519	    private boolean computeBulkSignupWarning(Owner owner) {
520	        LocalDate registrationDate = owner.getRegistrationDate();
521	        if (registrationDate == null) {
522	            return false;
523	        }
524	        long count = ownerRepository.findAll().stream()
525	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
526	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
527	            .count();
528	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
529	    }
530	
531	    @Override
532	    @Transactional(readOnly = true)
533	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
